 <?php $__env->startSection('content'); ?><h1>New Purchase</h1><form class="glass" method="post" action="<?php echo e(route('purchases.store')); ?>"><?php echo csrf_field(); ?><label>Supplier<select name="supplier_id"><option value="">None</option><?php $__currentLoopData = $suppliers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($s->id); ?>"><?php echo e($s->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><div id="purchaseRows"><?php $__currentLoopData = $products->take(3); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i=>$p): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="purchase-row"><select name="items[<?php echo e($i); ?>][product_id]"><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $q): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($q->id); ?>"><?php echo e($q->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input name="items[<?php echo e($i); ?>][quantity]" type="number" step=".001" value="1"><input name="items[<?php echo e($i); ?>][unit_cost]" type="number" step=".01" value="<?php echo e($p->purchase_price); ?>"></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><label>Paid<input name="paid" type="number" step=".01" value="0"></label><button class="primary">Receive Purchase</button></form><?php $__env->stopSection(); ?>
